style.css:
@-moz-document domain("calendar.google.com") {
/* Month view only: the month grid is the first grid inside main.
     Week and day views have several grids and look broken tilted. */
  [role="main"] > div > div [role="grid"]:first-of-type {
    transform: perspective(1600px) rotateX(9deg);
    transform-origin: 50% 0%;
    backface-visibility: hidden;
    will-change: transform;
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.2);
    border-radius: 12px;
    margin-bottom: 40px;
  }

  [role="gridcell"] {
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.5),
      inset 0 -2px 0 rgba(0, 0, 0, 0.06);
    transition: box-shadow 150ms ease;
  }

  /* Shadow-only hover: no transform, so layout never shifts */
  [role="gridcell"]:hover {
    box-shadow: 0 12px 22px rgba(0, 0, 0, 0.18);
  }

  [data-eventchip] {
    box-shadow: 0 3px 7px rgba(0, 0, 0, 0.25);
    transition: transform 120ms ease, box-shadow 120ms ease;
  }

  [data-eventchip]:hover {
    transform: translateY(-3px) scale(1.03);
    box-shadow: 0 10px 18px rgba(0, 0, 0, 0.3);
  }

  @media (prefers-reduced-motion: reduce) {
    [role="gridcell"], [data-eventchip] { transition: none; }
  }
}
